INSERT INTO public.users (id, email, password_hash, display_name, avatar_key, status, created_at, last_login_at) VALUES ('8859594d-a431-492d-a6e1-03ee66c61643', 'muzafon@gmail.com', '$2a$10$juO1UXhqhNWXJ/SnwkqMHOb5q5fpNtzbXfX0FXZT0.QzjiY4MZLa.', 'muzafon', 'default', 'ACTIVE', '2026-10-02 00:34:32.143694+00', '2026-10-09 21:53:39.785563+00');
INSERT INTO public.cases (id, code, title, description, status, created_by, created_at, updated_at, genre, age_limit, min_players, max_players, duration_minutes, price_cents, cover_media_id, map_media_id, entry_location_id, map_width, map_height) VALUES ('07501da7-4117-4722-9a5a-d824b70db044', 'CASE-002', 'Мармелад для Беллы', E'Кедровый Ручей, штат Орегон. Вторник, 6 октября.\nОдин дом сгорел. Возможно — не случайно.\nСледствие на месте не знает ни имён погибших, ни кто жил рядом, ни что здесь произошло на самом деле.\nУ вас два адреса на карте. Остальное — сами.\nГлавное - никому не верьте! Вас могут обманывать.', 'DRAFT', '8859594d-a431-492d-a6e1-03ee66c61643', '2026-10-03 22:25:07.548464+00', '2026-10-09 21:18:46.221395+00', 'DETECTIVE', 16, 1, 6, 90, 0, NULL, NULL, 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 2400, 1600);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('db7c948c-8df1-4c05-a239-84001babe5cc', '07501da7-4117-4722-9a5a-d824b70db044', '5140a5db-811d-448e-986e-b6257e89b872', 'Задний двор', 'Выход на задний двор', 'ROOM', 10, '2026-10-07 22:33:05.32214+00', '2026-10-08 00:38:52.077771+00', NULL, 48.495613, 11.904427, 'ON_EVIDENCE', '027ed5f2-a847-41b7-b166-59f2acca9dbb', 'Доступ к заднему двору разблокирован', 60, 60, 1.361526, 0, NULL, NULL);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('f473dd8d-1118-4006-951c-b1f3d9b8e294', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Штаб следственной группы', E'Походная палатка, развёрнутая у поворота на Кедровую.\n\nНа доске — карта с тремя адресами, телефон диспетчера, реестр домовладельцев. Здесь же — предварительные заключения и склад вещдоков.', 'OTHER', 5, '2026-10-03 22:25:07.548464+00', '2026-10-07 00:36:10.624525+00', NULL, 49.897118, 90.107704, 'ALWAYS', NULL, NULL, 1285, 521, 0.9146588, 79.27272, NULL, NULL);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', '07501da7-4117-4722-9a5a-d824b70db044', '5140a5db-811d-448e-986e-b6257e89b872', 'Второй этаж', E'Одна большая комната под скошенной крышей. Обгорела\nсильнее первого этажа — пожар шёл вверх. Балки потолка\nчерные, местами провалились, но пол держится.\n\nПространство делится на две половины без перегородки:\nслева — родительская кровать, шкаф, туалетный столик\nс треснувшим зеркалом. Справа — детский уголок: маленькая\nкровать с балдахином, сундук с игрушками, полка с книгами,\nстена в наклейках и рисунках.', 'ROOM', 30, '2026-10-07 23:51:03.403814+00', '2026-10-08 00:39:37.04794+00', NULL, 50.09906, 45.00822, 'ALWAYS', NULL, NULL, 60, 60, 1.7284247, 0, NULL, NULL);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('5140a5db-811d-448e-986e-b6257e89b872', '07501da7-4117-4722-9a5a-d824b70db044', 'a739950f-f4f0-488e-9d81-e97198d62969', 'Дом на Кедровой, 14', 'Сгоревший двухэтажный дом семьи Уитмор.', 'HOUSE', 0, '2026-10-06 22:01:52.582466+00', '2026-10-07 22:54:38.523798+00', NULL, 51.73587, 32.908867, 'ALWAYS', NULL, NULL, 875, 272, 6.5753236, 0, NULL, NULL);
