INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('f80abf0f-5dc3-4617-a1fb-a91954b37e4a', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Магазин Fern & Petal', 'Цветочный магазин в центре города. Здесь работает Натали.', 'BUILDING', 0, '2026-10-08 19:06:50.192605+00', '2026-10-09 02:27:54.333463+00', NULL, 50, 85, 'ON_EVIDENCE', 'eb0cc759-1889-4046-ab4a-9f03158dc842', 'Карта лояльности Quik-Gas оформлена на Н. Уитмор. Через неё оплачена покупка в понедельник', 890, 304, 1.0931467, -5.244713, NULL, NULL);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('a739950f-f4f0-488e-9d81-e97198d62969', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Усадьба Уитморов', 'Придомовая территория дома на Кедровой, 14.', 'HOUSE', 0, '2026-10-06 22:00:49.095498+00', '2026-10-08 00:21:16.478892+00', NULL, 51.36416, 90.79765, 'ALWAYS', NULL, NULL, 1570, 1, 0.84237915, 0, NULL, NULL);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('20579f3d-b2e1-42f4-9ce8-3bfa21bacde9', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Фабрика Arabella''s Marmalade Co', E'Адрес Мил-роуд, 400.  — «Arabella''s\nMarmalade Co. Основано 03.12».\n\nНесмотря на то, что в доме основателя произошёл пожар,\nфабрика работает. Сотрудники на местах, но говорят шёпотом.\nВ цеху пахнет яблоками и сахаром — варят новую партию.\n\nВнутри — ресепшн с рабочим местом ассистентки, коридор\nс кабинетами, лаборатория, тест-кухня, охрана, IT-серверная\nи отдельный кабинет партнёра — Маркуса Уитмора.', 'BUILDING', 0, '2026-10-07 23:34:29.537391+00', '2026-10-08 23:36:50.991644+00', NULL, 50, 85, 'ON_EVIDENCE', 'b306dc69-37d7-40c6-8f84-69104ce4277a', 'Перчатка с фабрики. Дырка в сетке — путь, которым вошёл тот, кто её оставил.', 1237, 42, 1.2997481, 0, NULL, NULL);
INSERT INTO public.locations (id, case_id, parent_id, name, description, location_type, sort_order, created_at, updated_at, media_id, entry_x, entry_y, discovery_mode, discovery_target_id, discovery_hint, map_x, map_y, scene_scale, scene_rotation, preview_media_id, map_media_id) VALUES ('b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Дом на Кедровой, 9', 'Дом Маркуса и Натали Уитмор. В километре от усадьбы Дэниела.', 'HOUSE', 0, '2026-10-08 19:25:38.638817+00', '2026-10-09 00:49:10.807054+00', NULL, 50, 85, 'ON_EVIDENCE', '0c80cf59-34b0-41d0-a95c-47ab2a5c6895', 'Второй пожар на Кедровой, 9. Два дома — один день.', 1477, 317, 0.8396051, 0, NULL, NULL);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('051a65f8-f497-4181-b982-6465bcbf278f', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Шкаф', 'Шкаф в спальне', 'CONTAINER', 'OPEN', 0, '2026-10-08 22:18:37.636283+00', '2026-10-08 22:50:23.553143+00', NULL, 40.47182, 14.658365, 2.504084, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('7d0da0ae-7072-40d3-b77c-aed6318b56c7', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Остатки таймера', E'Оплавленный пластиковый корпус на кухонном столе.\nРядом — обугленные провода, металлические контакты\nи остатки самодельного устройства. Похоже на механизм\nс часовым заводом.', 'ITEM', 'OPEN', 0, '2026-10-08 22:30:34.178393+00', '2026-10-08 22:30:49.456899+00', NULL, 68.705635, 53.135788, 0.6783015, 13.023631, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('aef789bd-beb4-4a70-89fc-cf5c5c5f38bb', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Пропуск в детский сад', E'Ламинированная карточка, лежит на полу в детской,\nрядом с кроватью. Валялась под кроватью, выпала\nиз чего-то. Край слегка оплавлен, но текст читается.', 'ITEM', 'OPEN', 0, '2026-10-08 01:10:04.956053+00', '2026-10-08 01:11:30.699323+00', NULL, 91.38859, 40.148308, 0.320801, -48.43531, 1, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('60fa58dc-c977-4c7e-98c6-4c6c5d7518e4', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Детский рисунок на шкафу', E'Небольшой рисунок, приколотый к шкафу кнопкой.\nВосковые мелки, неровные линии. Сбоку подпись\nдетской рукой: «Лили».', 'ITEM', 'OPEN', 0, '2026-10-07 21:06:22.430351+00', '2026-10-07 21:30:15.372556+00', NULL, 57.106365, 18.49104, 0.5019366, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('ae506cb2-41f3-4822-a75c-fde7abef9c9a', 'db7c948c-8df1-4c05-a239-84001babe5cc', 'Перчатки', 'Рабочая перчатка с логотипом фабрики Arabella. Посетите данное место возможно что-то узнаете.', 'ITEM', 'OPEN', 0, '2026-10-07 23:23:35.075565+00', '2026-10-08 01:35:48.600216+00', NULL, 56.358383, 69.26782, 1, 0, 0, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('f759f579-fb3d-4702-9fbd-46a3d62f8c87', '5140a5db-811d-448e-986e-b6257e89b872', 'Сумочка', E'Женская сумочка. Внутри — привычный\nженский набор и кое-что неожиданное.', 'CONTAINER', 'OPEN', 0, '2026-10-07 19:02:37.072767+00', '2026-10-07 19:03:56.707693+00', NULL, 13.842748, 51.78667, 0.6863725, -8.109493, 0, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('86b727fe-1263-4f64-a10b-c4bc027b4993', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Сундук с игрушками', E'Обгоревший деревянный сундук в углу детской.\nКрышка приоткрыта. Внутри — куклы и\nнесколько детских рисунков. Часть бумаг уцелела.', 'CONTAINER', 'OPEN', 0, '2026-10-08 00:51:42.898689+00', '2026-10-08 00:52:03.428886+00', NULL, 67.5688, 18.187424, 1.1180464, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('9c47fd91-22bd-46e3-b896-a44d85ce48b1', '5140a5db-811d-448e-986e-b6257e89b872', 'Пианино с фотографией', 'Обгоревшее пианино у стены. На верхней панели стоит фотография.', 'ITEM', 'CLOSED', 0, '2026-10-07 15:47:53.421969+00', '2026-10-07 15:48:17.994315+00', NULL, 19.66232, 18.739809, 2.564839, -2.6686988, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('b7330dab-a7cb-4ac6-ac52-5d428e241fb1', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Бумажка с телефоном психолога', E'Маленький клочок бумаги, сложенный вчетверо. Найден\nна столе. Почерк женский, ровный.', 'DOCUMENT', 'OPEN', 0, '2026-10-08 22:34:02.648813+00', '2026-10-08 22:34:23.726108+00', NULL, 18.28867, 56.255608, 0.3989293, -55.136635, 0, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('aee18f46-f540-4c6e-8b10-4f06a7d7dacd', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Кровать Натали', 'Отдельная кровать хозяйки дома', 'ITEM', 'CLOSED', 0, '2026-10-08 22:20:20.992282+00', '2026-10-08 22:20:52.865656+00', NULL, 80.04117, 20.469215, 2.2481577, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('3f4e238a-592a-439a-94c0-3b50598954da', '5140a5db-811d-448e-986e-b6257e89b872', 'Лестница на второй этаж', E'Лестница ведёт на второй этаж. На ней — следы чьих-то ног\nв пепле. Кто-то поднимался сюда после пожара.', 'DOOR', 'OPEN', 30, '2026-10-07 14:34:23.901301+00', '2026-10-08 00:39:27.143348+00', NULL, 50.20527, 44.803265, 2.2450135, 0, -1, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('89949bb4-bcab-418a-8642-d36b9fe10039', 'a739950f-f4f0-488e-9d81-e97198d62969', 'Детский домик Арабеллы', E'Розовый детский домик в саду, в стороне от большого дома.\nНад входом — вырезанное сердце. Рядом качели и маленькая горка\nв тон. У дорожки — табличка с именем и сердечком.', 'CONTAINER', 'CLOSED', 30, '2026-10-07 00:46:37.430809+00', '2026-10-07 13:17:00.339775+00', NULL, 24.358093, 69.71993, 4.3227715, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('8a5779a4-3008-416f-af9b-d994f8d64635', 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 'Телефон для вызова', 'Городской телефон штаба. Набираешь номер — тебя соединяют.', 'INTERROGATION_PHONE', 'OPEN', 0, '2026-10-09 02:02:52.830225+00', '2026-10-09 02:04:51.713875+00', NULL, 30.602581, 17.328615, 0.75076073, 0, 0, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('0e32df0a-7276-45f2-a7f8-6421211af785', '5140a5db-811d-448e-986e-b6257e89b872', 'Журнальный столик', E'Журнальный столик, на котором разбросаны документы, будто кто-то что-то искал и не нашёл.\nРядом — кухонный нож со следами крови и тёмный телефон\nс разбитым экраном, заблокированный PIN-кодом.', 'CONTAINER', 'OPEN', 0, '2026-10-07 20:16:24.765851+00', '2026-10-09 21:28:30.925453+00', NULL, 22.276257, 59.422337, 1.0974786, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('56f2234d-3f33-41fe-bb38-165932a2da4c', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Расписание садика', E'Небольшая расписание детского сада \nна столе.', 'DOCUMENT', 'OPEN', 0, '2026-10-07 21:08:47.810081+00', '2026-10-07 21:32:00.915112+00', NULL, 59.09601, 40.380203, 0.3213547, 7.356187, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('d6baff48-95f3-425c-9c82-951579e7b583', '5140a5db-811d-448e-986e-b6257e89b872', 'Контур меловой в гостиной', 'Очертания взрослого человека.', 'ITEM', 'OPEN', 20, '2026-10-07 14:27:32.600781+00', '2026-10-07 21:43:45.892004+00', NULL, 36.54868, 48.646027, 1.7300876, 0, 1, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('98c8b4bb-0d6a-4f6e-a06f-d73ead8adba3', '5140a5db-811d-448e-986e-b6257e89b872', 'Кухонный гарнитур', E'Кухонный гарнитур вдоль дальней стены. Верхние шкафчики\nобгорели, но нижние ящики и столешница уцелели. На столешнице\nразложены вещи, которые обычно лежат под рукой у хозяйки:\nнож, разделочная доска, детская кружка.', 'CONTAINER', 'OPEN', 0, '2026-10-07 19:48:35.928894+00', '2026-10-07 19:56:54.205753+00', NULL, 79.84636, 12.754542, 3.233414, 0.018272182, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('d279d23f-9517-4b22-b587-0974f079cc04', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Блокнот Натали', 'Небольшой блокнот в клетку.', 'ITEM', 'OPEN', 0, '2026-10-08 22:23:55.964817+00', '2026-10-09 21:37:54.622913+00', NULL, 60.90113, 12.698629, 0.43856746, 0, 0, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('6b693713-e2f3-4373-b36a-0bf9275b9ab1', '5140a5db-811d-448e-986e-b6257e89b872', 'Кухонный стол', E'Массивный деревянный стол в кухонной зоне. Поверхность\nпокрыта копотью, но кое-что уцелело: пара кружек, детская\nтарелка с обугленным рисунком, рассыпанные салфетки.\nБлиже к краю, у самой кромки, лежит связка ключей.', 'ITEM', 'OPEN', 0, '2026-10-07 15:53:01.597891+00', '2026-10-07 22:44:47.540513+00', NULL, 71.93629, 42.051666, 3.757105, 0, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('869efa4c-817c-4278-9138-88f6e14b0249', '5140a5db-811d-448e-986e-b6257e89b872', 'Дверь на задний двор', E'Стеклянная дверь, ведёт на заднюю\nтеррасу. Створка цела, но заперта — замок повёрнут\nс той стороны. Стекло слегка закопчено, но через него\nвидно двор: на земле лежит что-то тёмное, у сетчатого\nзабора — пролом. Снаружи дверь закрыта на ключ.\n\nЗамок простой, механический. Нужно найти ключи', 'DOOR', 'CLOSED', 10, '2026-10-07 20:30:59.63369+00', '2026-10-07 22:55:29.627704+00', NULL, 48.84137, 11.356286, 1.8751981, 0, -1, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('f31639bf-f55d-47a0-8ccd-47391ca15609', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Сейф — открытый', E'Большой сейф выломанный. Внутри — три папки и рассыпанные по дну обгоревшие\nбумаги. Часть документов уцелела.', 'ITEM', 'CLOSED', 0, '2026-10-08 01:02:29.352798+00', '2026-10-08 01:02:47.505219+00', NULL, 62.14414, 54.855865, 2.1517217, 2.7418075, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('4d240448-08bb-4951-abba-2269e4713cff', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Гирлянда «Белле 6!»', E'Гирлянда из бумажных букв.\nс надписью Бэлле 6.', 'ITEM', 'OPEN', 0, '2026-10-08 00:56:14.010205+00', '2026-10-08 01:36:17.242011+00', NULL, 67.00139, 8.762828, 1.3526402, -1.9996712, 0, false);
