INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('9853bba2-4fa7-4a66-a84f-1b27a9b8bfcf', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Договор о расторжении брака', E'Плотная канцелярская папка с документами, лежит\nна журнальном столике. Внутри — типовой бланк\nюридической фирмы, заполненный от руки.', 'DOCUMENT', 'OPEN', 0, '2026-10-08 22:37:14.88819+00', '2026-10-08 22:37:53.166078+00', NULL, 25.841068, 26.934929, 0.34680417, 0, 0, true);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('06987571-6ae1-4dd5-ba46-9d8818bf93f8', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Журнал ворот', E'Потрёпанный журнал, с записями охранника.\nПоследние строки — за вторник, 6 октября.', 'ITEM', 'CLOSED', 0, '2026-10-07 21:03:20.135507+00', '2026-10-07 21:31:38.00673+00', NULL, 44.326122, 38.047577, 1, 3.095375, 0, false);
INSERT INTO public.game_objects (id, location_id, name, description, object_type, state, sort_order, created_at, updated_at, media_id, pos_x, pos_y, scene_scale, scene_rotation, render_layer, walkable) VALUES ('f6bff247-7200-4b0f-b04b-ad49064f444c', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Ноутбук охраны', E'Рабочий ноутбук на столе. Экран горит, система\nвидеонаблюдения открыта. На экране — сетка из четырёх\nокон: три камеры работают, одна — нет.', 'COMPUTER', 'OPEN', 0, '2026-10-07 21:00:09.39835+00', '2026-10-07 21:32:25.183001+00', NULL, 54.755627, 39.72409, 1, 0, 0, false);
