INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('5bef52f4-b6b3-4b7c-b42d-cee76eb20e08', '07501da7-4117-4722-9a5a-d824b70db044', '89949bb4-bcab-418a-8642-d36b9fe10039', 'a739950f-f4f0-488e-9d81-e97198d62969', 'Табличка у детского домика', NULL, 'Видимо у этого домика есть своя хозяйка. Её зовут Арабелла.', 'DOCUMENT', 'SUPPORTING', 20, '2026-10-07 01:17:54.960483+00', '2026-10-07 13:29:02.110404+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('9d35ea5d-7c9d-48bf-8385-5724577a2c67', '07501da7-4117-4722-9a5a-d824b70db044', 'a7409994-d2d1-478c-8d6a-a59c490796cb', '5140a5db-811d-448e-986e-b6257e89b872', 'Фотография дочки на дверце', NULL, E'Небольшая фотография прикреплена магнитом к дверце\nхолодильника, с подписью «Белле 6 лет. 14 октября».', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-07 19:58:08.55167+00', '2026-10-07 21:59:15.353528+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('891e6600-865d-4746-8be6-3eb65b84adaf', '07501da7-4117-4722-9a5a-d824b70db044', 'f6bff247-7200-4b0f-b04b-ad49064f444c', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Журнал видеонаблюдения', NULL, E'Система видеонаблюдения усадьбы. Раздел «Состояние камер».\n\nКамера 1 (ворота) — активна, запись идёт.\nКамера 2 (Задний двор) — неактивна.\nПоследняя запись: суббота, 3 октября, 17:42.\n\nКто-то отключил её изнутри системы — заранее, спокойно,\nпо штатной заявке.', 'DIGITAL', 'KEY', 0, '2026-10-07 21:02:07.86103+00', '2026-10-07 21:28:14.715674+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('1560bfc1-3458-4894-ae34-87e0a9bd70b5', '07501da7-4117-4722-9a5a-d824b70db044', '9c47fd91-22bd-46e3-b896-a44d85ce48b1', '5140a5db-811d-448e-986e-b6257e89b872', 'Семейная фотография', NULL, E'Фотография в рамке. На ней мужчина,\nженщина и маленькая девочка. На обратной\nстороне — детская подпись: «я ❤ папа ❤ мама».\n\nЛица не подписаны. Кто именно изображён — неизвестно.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-07 15:49:59.719005+00', '2026-10-07 18:58:33.874525+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('3f30bb96-ff47-4d2d-b9f1-796e56379a90', '07501da7-4117-4722-9a5a-d824b70db044', 'f759f579-fb3d-4702-9fbd-46a3d62f8c87', '5140a5db-811d-448e-986e-b6257e89b872', 'Водительское удостоверение Клэр Уитмор', NULL, E'Фамилия: Уитмор\nИмя: Клэр\nДата рождения: 14 марта\nВозраст: 34 года\nАдрес: Кедровая, 14\nКатегория: B (легковые)', 'DOCUMENT', 'KEY', 0, '2026-10-07 19:36:53.754152+00', '2026-10-07 19:36:53.754152+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('1ee4bdff-3827-4e0b-8a1a-e791cb53b2c7', '07501da7-4117-4722-9a5a-d824b70db044', '0e32df0a-7276-45f2-a7f8-6421211af785', '5140a5db-811d-448e-986e-b6257e89b872', 'Кухонный нож', NULL, E'Большой кухонный нож, на лезвии — тёмные\nпятна, похожие на кровь. \n\nНож мог быть здесь и до пожара. Мог быть и после —\nкто-то оставил его на столе, перебирая бумаги.', 'PHYSICAL', 'SUPPORTING', 0, '2026-10-07 20:25:16.396953+00', '2026-10-07 20:25:16.396953+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('70110406-e7e7-4758-ad41-a9dad0ce5065', '07501da7-4117-4722-9a5a-d824b70db044', '60fa58dc-c977-4c7e-98c6-4c6c5d7518e4', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Детский рисунок Лили', NULL, E'Рисунок восковыми мелками. Изображены две фигурки:\nбольшая (взрослый) и маленькая (ребёнок). Большая\nфигурка держит маленькую за руку. Обе улыбаются.\nПодпись детской рукой: Лили.\nКто такая Лили — неизвестно. Рисунок висит на шкафу.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-07 21:07:42.943977+00', '2026-10-07 21:26:25.579854+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('20d868ff-f077-439e-9fb0-92d7324443bb', '07501da7-4117-4722-9a5a-d824b70db044', '56f2234d-3f33-41fe-bb38-165932a2da4c', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Расписание детского сада', NULL, E'Расписание детского сада «Little Sprouts».\n\nСтандартный день: 08:00 — 17:00.\nВторник: 08:00 — 13:00 (сокращённый день).\nПометка ручкой, красным: «вторник — 13:00!!!»', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-07 21:09:48.81772+00', '2026-10-07 21:28:58.78851+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('52ea901c-b3d7-43d3-8e30-87612bf19023', '07501da7-4117-4722-9a5a-d824b70db044', '4d240448-08bb-4951-abba-2269e4713cff', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Гирлянда «Белле 6!»', NULL, E'Бумажная гирлянда на стене детской. Вырезанные буквы\nи восклицательный знак. Читается: «Белле 6!».\n\nДевочке исполнилось бы шесть. Гирлянду готовили заранее,\nк дню рождения. Он ещё не наступил.', 'PHYSICAL', 'KEY', 0, '2026-10-08 00:58:25.567365+00', '2026-10-08 00:58:25.567365+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('848c20dd-b381-42c9-be8c-cd9ee108e51b', '07501da7-4117-4722-9a5a-d824b70db044', '051a65f8-f497-4181-b982-6465bcbf278f', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Пустой шкаф', NULL, 'Почти вся одежда вынесена.', 'PHYSICAL', 'SUPPORTING', 0, '2026-10-08 22:21:45.374504+00', '2026-10-08 22:21:45.374504+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('595c5629-d17c-4174-a9a6-4ee10db93b5d', '07501da7-4117-4722-9a5a-d824b70db044', 'aee18f46-f540-4c6e-8b10-4f06a7d7dacd', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Отделбная кровать Натали', NULL, 'Видимо хозяева часто ночевали в разных комнатах.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 22:22:57.625232+00', '2026-10-08 22:22:57.625232+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('a2601794-112f-4776-bc67-fc31053cadc1', '07501da7-4117-4722-9a5a-d824b70db044', '7d0da0ae-7072-40d3-b77c-aed6318b56c7', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Остатки таймера на кухне', NULL, E'Оплавленный корпус самодельного устройства. Внутри\nуцелел часовой механизм с отметкой «13:45».\n\nПожар на кухне начался именно в 13:45 — на тридцать\nминут позже, чем в доме на Кедровой, 14.\n\nУстройство сработало по времени.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 22:31:38.70488+00', '2026-10-08 22:31:38.70488+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('027ed5f2-a847-41b7-b166-59f2acca9dbb', '07501da7-4117-4722-9a5a-d824b70db044', '6b693713-e2f3-4373-b36a-0bf9275b9ab1', '5140a5db-811d-448e-986e-b6257e89b872', 'Ключи от дома', NULL, E'Связка ключей на брелоке с надписью «Кедровая, 14».\nТри ключа: один похож на входной, один — на заднюю дверь,\nтретий небольшой, вероятно от почтового ящика или гаража.\n\nНа брелоке — гравировка с инициалами «D.W.» и датой «03.12».\n\nВторой ключ подходит к стеклянной двери на террасу — той,\nчто заперта снаружи. Кто-то запер дом с заднего двора', 'PHYSICAL', 'SUPPORTING', 0, '2026-10-07 16:13:48.435855+00', '2026-10-07 16:13:48.435855+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('a2f988bc-4511-4b34-af3e-eabae276ff5e', '07501da7-4117-4722-9a5a-d824b70db044', 'f759f579-fb3d-4702-9fbd-46a3d62f8c87', '5140a5db-811d-448e-986e-b6257e89b872', 'Косметичка', NULL, E'Небольшая модная косметичка.\nВидимо хозяйка любила ухаживать за собой.', 'PHYSICAL', 'SUPPORTING', 0, '2026-10-07 19:38:48.237788+00', '2026-10-07 20:51:38.499861+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('4c728b48-729e-4e8f-b523-d27ca7b5ae3e', '07501da7-4117-4722-9a5a-d824b70db044', 'de0ae316-9e18-40e0-bfb8-b4075bdf7003', 'db7c948c-8df1-4c05-a239-84001babe5cc', 'Канистра с бензином', NULL, E'Канистра для бензина.\n\nНа боку — наклейка с заправки «Quik-Gas».\nЧитается:\n• Колонка 4\n• Время: понедельник, 09:12\n• Оплата: карта лояльности\n\nКанистра почти пустая — остатки бензина испарились\nза три дня.\n\nПонедельник, 09:12 — покупка за день до пожара по карте лояльности.', 'PHYSICAL', 'KEY', 0, '2026-10-07 23:21:45.22947+00', '2026-10-07 23:21:45.22947+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('b3a96321-db46-4cc2-a9c0-d37e098a7d31', '07501da7-4117-4722-9a5a-d824b70db044', '71fa2839-e15d-4a54-9d51-f464be03850b', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Бирка с именем на зайце', NULL, 'Бирка с именем на зайце Anabella созвучным с именем девочки', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 00:49:51.451099+00', '2026-10-08 00:49:51.451099+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('3173c4da-d6bf-42b2-9e14-875ad2f949c2', '07501da7-4117-4722-9a5a-d824b70db044', 'fefecca7-7eeb-4f19-be28-3db0eb9cdaa6', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Фотография Клэр и Нэт', NULL, E'Небольшая фотография в рамке.\n\nНа ней — две женщины. \n\nПервая — та же женщина, что на водительском\nудостоверении и на семейной фотографии: Клэр.\n\nВторая — не из документов следствия. Тёмные волосы,\nкороткая стрижка, открытая улыбка. Неизвестная.\n\nСнизу, женским почерком, синей ручкой:\n\n«Клэр + Нэт. 15 лет вместе».\n\nКто такая Нэт — предстоит выяснить. Единственное,\nчто о ней известно: она была лучшей подругой Клэр\nи дружила с ней пятнадцать лет.', 'PHOTO', 'KEY', 0, '2026-10-08 01:09:14.166622+00', '2026-10-08 01:09:14.166622+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('724902a3-a3b9-4186-a8a7-4bcd82f18054', '07501da7-4117-4722-9a5a-d824b70db044', '0e32df0a-7276-45f2-a7f8-6421211af785', '5140a5db-811d-448e-986e-b6257e89b872', 'Мобильный телефон', NULL, E'Мобильный телефон с разбитым экраном.\nНа экране блокировки — фотография девочки с воздушным\nшариком. Неизвестно чей это телефон.', 'DIGITAL', 'SUPPORTING', 0, '2026-10-07 20:26:50.994952+00', '2026-10-08 21:13:12.282312+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('885ac2d7-e82f-44e0-ac7a-0c7dc6ebfc2f', '07501da7-4117-4722-9a5a-d824b70db044', 'd279d23f-9517-4b22-b587-0974f079cc04', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Блокнот Натали', NULL, E'Небольшой блокнот в клетку. На последней исписанной\nстранице — строки, сделанные женским почерком:\n\nНашла бумаги в ящике. Cedar Citrus.\nМоё имя внизу. Подпись не ...\n\nДальше запись обрывается. Страница вырвана.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 22:26:13.045198+00', '2026-10-08 22:26:13.045198+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('b3dad80f-09a5-44f1-ab95-b137e04780e9', '07501da7-4117-4722-9a5a-d824b70db044', '869efa4c-817c-4278-9138-88f6e14b0249', '5140a5db-811d-448e-986e-b6257e89b872', 'Дверь заперта снаружи', NULL, E'Дверь на террасу заперта, причём снаружи.\nВнутри на ручке — следы копоти, снаружи — нет.\nЗамок повёрнут ключом с той стороны.\n\nЗначит, кто-то запер дом со стороны заднего двора\nдо пожара. Возможно, чтобы никто не вышел.\nВозможно, чтобы никто не вошёл.', 'PHYSICAL', 'KEY', 0, '2026-10-07 20:32:46.260215+00', '2026-10-07 20:32:46.260215+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('b306dc69-37d7-40c6-8f84-69104ce4277a', '07501da7-4117-4722-9a5a-d824b70db044', 'ae506cb2-41f3-4822-a75c-fde7abef9c9a', 'db7c948c-8df1-4c05-a239-84001babe5cc', 'Перчатка с логотипом фабрики', NULL, E'Рабочие перчатки с логотипом фабрики\n«Arabella''s Marmalade Co.»\n\nЭто фирменная перчатка с фабрики Уитморов.\nТакие выдают сотрудникам в лаборатории.\n\nПерчатку мог оставить только тот, кто имеет доступ\nна фабрику. Отправляйтесь на фабрику, возможно там, что-то узнаете.', 'PHYSICAL', 'KEY', 0, '2026-10-07 23:26:01.349858+00', '2026-10-07 23:46:51.653218+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('b5e42aff-2d9b-4266-85e2-fab92b382c28', '07501da7-4117-4722-9a5a-d824b70db044', 'aef789bd-beb4-4a70-89fc-cf5c5c5f38bb', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Пропуск в детский сад', NULL, E'Ламинированная карточка-пропуск детского сада\n«Little Sprouts».\n\nФИО: Арабелла Уитмор\nГруппа: старшая (5–6 лет)\nДата поступления: 2 года назад\nОтветственный: Т. Рейес\n\nНа обороте — таблица с подписями о том, кто\nзабирал ребёнка. Каждый день — две подписи.\nЧаще всего: «К. Уитмор» (утром) и «Д. Уитмор» (вечером).\n\nВ графе вторника последняя запись: «Т. Рейес».\nРядом — маленькая детская пометка фломастером.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 01:13:22.184676+00', '2026-10-08 01:13:22.184676+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('79867f9e-ef87-4828-a55d-9eae20a953bb', '07501da7-4117-4722-9a5a-d824b70db044', 'f31639bf-f55d-47a0-8ccd-47391ca15609', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Банковские выписки', NULL, E'Три банковские выписки за последние полгода.\nКредитор — фабрика Arabella''s Marmalade Co.\nПолучатель — компания Cedar Citrus Supply LLC.\n\nОбщая сумма переводов: около 3 800 000 долларов.\nОснование в каждой выписке: «оплата за цитрусовые».\n\nCedar Citrus Supply LLC зарегистрирована по адресу,\nкоторого не существует. По базе компания не находится.\nПоставок цитрусовых фабрика не получала — это видно\nпо складским журналам.\n\nКто-то платил за то, чего не было. Регулярно,\nаккуратно, крупными частями.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 01:26:41.501607+00', '2026-10-08 01:26:41.501607+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('19e7ec01-d89f-44a5-8d94-9d61240f4f39', '07501da7-4117-4722-9a5a-d824b70db044', 'f31639bf-f55d-47a0-8ccd-47391ca15609', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Соглашение о наследовании', NULL, E'Копия соглашения между партнёрами фабрики\nArabella''s Marmalade Co. Дата подписания — три года назад.\n\nПункт 7.3, выделен жёлтым маркером:\n\n«В случае, если владелец и его прямые наследники\nпогибают, его доля переходит ближайшим доверенным\nлицам — семье, близким друзьям и даже работникам, указанным\nвладельцем в отдельном распоряжении».\n\nПодпись владельца есть. Подпись второго партнёра есть.\nПриложения к соглашению — отдельный лист с именами\nдоверенных лиц — отсутствует. Страница вырвана.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 01:25:17.106134+00', '2026-10-08 01:38:21.851964+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('b065277d-6547-40f8-b5e2-796d3779913b', '07501da7-4117-4722-9a5a-d824b70db044', '53f7e426-ad0c-4c2a-8f96-b3b7574b4a9f', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Выписки Cedar Citrus с подписью Натали', NULL, E'Пачка банковских выписок и договоров с компанией\nCedar Citrus Supply LLC.\n\nВнизу каждой страницы — подпись «N. Whitmore».\nПодпись выглядит ровной, слишком аккуратной.\nДоговоры оформлены на имя Натали.', 'DOCUMENT', 'KEY', 0, '2026-10-08 22:29:15.700851+00', '2026-10-08 22:29:15.700851+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('83a8573e-0947-4a29-86d9-c8fcf680c649', '07501da7-4117-4722-9a5a-d824b70db044', 'a7409994-d2d1-478c-8d6a-a59c490796cb', '5140a5db-811d-448e-986e-b6257e89b872', 'Стикеры с надписями', NULL, E'На дверце холодильника — несколько стикеров\nи записок, прикреплённых магнитами. Почерк разный.\n\nСтикер 1, женский ровный почерк:\n«Дэн, заехать за подарком для Беллы».\nСтрелка вниз к магниту с фотографией девочки.\n\nСтикер 2, мужской быстрый почерк, карандаш:\n«Аудит — чт. 8. Не забыть договоры».\nПодчёркнуто дважды.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-07 20:05:13.169959+00', '2026-10-07 20:05:13.169959+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('eb0cc759-1889-4046-ab4a-9f03158dc842', '07501da7-4117-4722-9a5a-d824b70db044', '17f8ce70-0cc1-4150-a8f4-e44774c783f6', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Дисконтная карта Quik-Gas', NULL, E'Пластиковая карта лояльности сети заправок «Quik-Gas».\n\nНа лицевой стороне выбито имя владельца заправки:\n«N. Whitmore».\n\nЧерез эту карту в понедельник 5 октября в 09:12\nбыла оплачена покупка канистры на заправке\n«Quik-Gas», колонка 4.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 22:50:04.237938+00', '2026-10-08 22:50:04.237938+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('0fc4d974-bf9d-4148-8f6a-104c6cea414d', '07501da7-4117-4722-9a5a-d824b70db044', 'f31639bf-f55d-47a0-8ccd-47391ca15609', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Письмо из банка об аудите', NULL, E'Письмо из банка, датированное прошлой неделей.\n\n«Уважаемый мистер Уитмор,\n\nв связи с плановой проверкой вашей компании\nпросим предоставить документы по контрагенту\nCedar Citrus Supply LLC.\n\nПроверка назначена на четверг, 8 октября, 10:00.\nПрисутствие обоих партнёров обязательно.\n\nС уважением,\nотдел финансового мониторинга».\n\nВнизу — приписка от руки, синей ручкой:\n«8 — аудит!»', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 01:28:06.149705+00', '2026-10-08 01:28:06.149705+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('f1de7b68-5fb7-40a0-b3f4-25171bcdb926', '07501da7-4117-4722-9a5a-d824b70db044', '64d28b74-3ee6-4956-8078-60b539fbf2b8', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Второй контур в детской', NULL, E'На матрасе детской кроватки — маленький меловой контур.\nОчертания ребёнка, лет шести. Сделан уже после того,\nкак огонь потушили.\n\nРядом, на полу, лежит обгоревший плюшевый заяц.\nОн оплавлен, но бирка на уцелевшем ухе ещё читается.\n\nВзрослый — на первом этаже. Ребёнок — здесь.\nДвое погибших.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 00:47:10.930074+00', '2026-10-08 01:39:35.219183+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('6769ac9d-6874-493d-ba05-78568a811194', '07501da7-4117-4722-9a5a-d824b70db044', '11247f9e-7512-4087-ad69-59da6ac9145b', 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 'Выписка из реестра · Кедровая, 14', 'Кадастровая выписка. Один лист, печатный.', E'Адрес: Кедровая, 14.\nВладелец: Дэниел Уитмор.', 'DOCUMENT', 'SUPPORTING', 10, '2026-10-06 17:20:50.645963+00', '2026-10-06 18:05:13.745757+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('0c80cf59-34b0-41d0-a95c-47ab2a5c6895', '07501da7-4117-4722-9a5a-d824b70db044', '06b9b350-6f63-41a6-a22f-97ce1758d7c6', 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 'Выписка из реестра · Кедровая, 9', 'Кадастровая выписка. Один лист, печатный.', E'Адрес: Кедровая, 9.\nВладелец: Натали Уитмор.', 'DOCUMENT', 'SUPPORTING', 20, '2026-10-06 17:21:23.22597+00', '2026-10-06 18:06:07.522691+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('ed95c7db-fdd6-4c79-875c-177d994c1eae', '07501da7-4117-4722-9a5a-d824b70db044', 'ab00a8ad-ef84-4420-a65f-fe9495ecac67', 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 'Календарь · Отмеченные даты', 'Календарь со стены штаба. Три даты обведены.', E'Октябрь.\n\n6 октября — обведено двойным кругом красным маркером.\n\n8 октября — обведено пунктирным синим кругом.\n\n14 октября — обведено розовым кругом, сильнее остальных.\n\nНикаких подписей рядом нет. Возможно, это как-то поможет.\nНо, возможно, и нет.', 'DOCUMENT', 'SUPPORTING', 30, '2026-10-06 19:48:38.107277+00', '2026-10-06 19:48:38.107277+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('2d66977f-2eab-4e9c-9c6a-4727872c06a9', '07501da7-4117-4722-9a5a-d824b70db044', '56bfd0af-0727-4777-ad3b-3141ee2b9642', 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 'Выписка ГИБДД · Транспорт семьи', 'Регистрационные данные на транспорт. Три записи.', E'Кедровая, 14\n\nТёмно-синий Мерседес, госномер 3ND-741.\nВладелец: Дэниел Уитмор.\n\n\nКедровая, 9\n\nБелый внедорожник, госномер 7KD-117.\nВладелец: Натали Уитмор.\n\nКрасный хэтчбек, госномер 4AB-289.\nВладелец: Натали Уитмор.', 'DOCUMENT', 'SUPPORTING', 40, '2026-10-06 20:33:32.252624+00', '2026-10-06 20:33:32.252624+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('d72cb9ed-75c1-4d72-a4b3-2da922fc1639', '07501da7-4117-4722-9a5a-d824b70db044', 'b7330dab-a7cb-4ac6-ac52-5d428e241fb1', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Телеофн психолога', NULL, E'Клочок бумаги с надписью:\n\n«Д-р Холт — 555-0234\nпн, ср, пт. Приём с 10:00»\n\nНи фамилии, ни адреса. Только телефон и расписание.\nНиже, тем же почерком, мельче:\n\n«Спросить про тревогу. Про то, что не могу решиться.\nПро то, что боюсь.»\n\nНикаких имён. Но кто-то записывал это для себя,\nаккуратно, несколько раз перечитав.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 22:36:16.01111+00', '2026-10-08 22:36:16.01111+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('57b514a5-ff22-4fe8-b77b-6f8f99145208', '07501da7-4117-4722-9a5a-d824b70db044', '7fb21a01-11f5-48ed-9ded-020ece0db53b', 'f473dd8d-1118-4006-951c-b1f3d9b8e294', 'Дорожная камера · 12:48', 'Кадр с дорожной камеры на трассе Кедровый хребет.', E'Запись с дорожной камеры на трассе Кедровый хребет.\n\nВторник, 6 октября. 12:48.\n\nБелый внедорожник, госномер 7KD-117.\nЕдет со стороны города в направлении Кедровой.\n\nВодителя не разглядеть. На заднем сидении ничего не видно.\n\nБольше на записи никого нет.', 'DIGITAL', 'SUPPORTING', 70, '2026-10-06 20:59:06.628947+00', '2026-10-06 21:09:46.391586+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('c782b980-a4ec-44fb-a9a0-c903a13d5cf3', '07501da7-4117-4722-9a5a-d824b70db044', '0e32df0a-7276-45f2-a7f8-6421211af785', '5140a5db-811d-448e-986e-b6257e89b872', 'Разбросанные документы', NULL, E'Среди уцелевших бумаг:\nстраховой полис дома на Кедровой, 14 — на имя Дэниела Уитмора,\nписьмо из банка с уведомлением о крупном переводе 3 800 000 долларов\n\nКто-то очень хотел найти здесь что-то конкретное.\nИ, судя по разбросанным бумагам, не нашёл.', 'DOCUMENT', 'KEY', 0, '2026-10-07 20:21:26.592171+00', '2026-10-07 20:21:26.592171+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('273ac8ab-6957-4bd1-a179-807bc3ed5236', '07501da7-4117-4722-9a5a-d824b70db044', '06987571-6ae1-4dd5-ba46-9d8818bf93f8', 'd0e58dbb-c60c-4811-9d07-c2a7f86cd768', 'Записи журнала ворот', NULL, E'Журнал ворот усадьбы. Вторник, 6 октября.\n\n08:00 — дежурство принял. Т. Рейес.\n11:00 — выезд Д. Уитмора (на работу).\n12:55 — отлучка (личное). Запер ворота.\n13:40 — вернулся, ворота открыл.\n14:15 — выезд на место (по вызову диспетчера).\n\nБольше за этот день в журнале записей нет.\nНикто, кроме охранника, через ворота не выезжал\nи не въезжал.\n\nМежду 12:55 и 13:40 ворота были заперты.', 'DOCUMENT', 'KEY', 0, '2026-10-07 21:04:47.356564+00', '2026-10-07 21:58:17.085504+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('fa3e4870-984b-42bc-a730-cd2eed8075f4', '07501da7-4117-4722-9a5a-d824b70db044', '86b727fe-1263-4f64-a10b-c4bc027b4993', 'a4c4fdfc-43e5-4338-b0c3-c0899a7b52cd', 'Детский рисунок «Дядя Маркус»', NULL, E'Детский рисунок, лежит в сундуке\nс игрушками. Уцелел почти полностью.\n\nИзображён Мужчина с девочкой и надпись Дядя Маркус.\n\nВ углу рисунка — дата, нарисованная тем же почерком:\n«Понедельник».', 'PHOTO', 'KEY', 0, '2026-10-08 00:55:01.712208+00', '2026-10-08 00:55:01.712208+00', NULL);
INSERT INTO public.evidences (id, case_id, object_id, location_id, title, description, content_text, evidence_type, importance, sort_order, created_at, updated_at, media_id) VALUES ('d760f931-67f8-4c68-b559-e63432bc46fe', '07501da7-4117-4722-9a5a-d824b70db044', '9853bba2-4fa7-4a66-a84f-1b27a9b8bfcf', 'b8f1fbc5-cb4f-4d38-9f5a-06f97b7dc1ef', 'Договор о расторжении брака', NULL, E'Типовой договор на оказание юридических услуг\nпо расторжению брака.\n\nЮридическая фирма: Hart & Lowell.\nКлиент: Н. Уитмор.\nДата составления: 5 октября, понедельник.\n\nГрафа «причина обращения» заполнена от руки:\nИмущественные споры.\nНиже — приписка юриста, уже другим почерком,\nсиней ручкой:\n«Назначена консультация на среду, 13:00.\nПри себе иметь: паспорт, документы на дом,\nвыписки банка».\nДоговор не подписан.', 'DOCUMENT', 'SUPPORTING', 0, '2026-10-08 22:39:26.100783+00', '2026-10-08 22:39:26.100783+00', NULL);
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('c0b375be-b167-4427-954f-ca6d861d209d', '07501da7-4117-4722-9a5a-d824b70db044', 'f80abf0f-5dc3-4617-a1fb-a91954b37e4a', 'Джози', 'Коллега Натали по магазину Fern & Petal. Хамоватая девушка 25 лет, дорогой макияж, фартук с логотипом цветочного магазина. Периодически поглядывает на телефон.', NULL, NULL, 0, '2026-10-08 20:03:38.611381+00', '2026-10-08 23:46:19.602209+00', 49.475098, 50.6105, 2.2466874, 0, NULL, 'AUTO', NULL);
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('93fe7e5c-bd6a-44cc-9fea-10e2637834ee', '07501da7-4117-4722-9a5a-d824b70db044', '1ec8fc06-7be9-4f0d-8fc0-8c02897f93e4', 'Мисс Доббс', 'Воспитательница детского сада Little Sprouts. Женщина 45 лет, русые волосы убраны в пучок, мягкие черты лица, тёплая улыбка. Свитер пастельного цвета, на груди — бейдж Little Sprouts.', NULL, NULL, 0, '2026-10-08 20:05:22.445023+00', '2026-10-08 23:51:57.890421+00', 47.52897, 59.22177, 2.4308646, 0, NULL, 'AUTO', NULL);
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('236b49ce-db70-40ab-9720-3d5545c11277', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Дэниел Уитмор', 'Мужчина 38–40 лет, тёмные волосы с проседью, усталое лицо, рубашка навыпуск, без пиджака. Выжил, потому что был на работе. Выглядит разбитым, но держится. На левой руке — обручальное кольцо.', NULL, NULL, 0, '2026-10-08 19:52:30.803642+00', '2026-10-09 02:23:29.618711+00', 50, 50, 1, 0, NULL, 'EVIDENCE_FOUND', '6769ac9d-6874-493d-ba05-78568a811194');
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('5e9cddc7-dfb7-47e3-8e5e-4652d046a19b', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Маркус Уитмор', 'Брат Дэниела, партнёр с 30% долей. Любезен, помогает следствию. Потерял дом — но выглядит собранным.', NULL, NULL, 0, '2026-10-08 19:54:09.883931+00', '2026-10-09 02:23:50.271816+00', 50, 50, 1, 0, NULL, 'EVIDENCE_FOUND', '0c80cf59-34b0-41d0-a95c-47ab2a5c6895');
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('2498dfcf-2ead-4d13-b9a7-264aa00dab0f', '07501da7-4117-4722-9a5a-d824b70db044', '20579f3d-b2e1-42f4-9ce8-3bfa21bacde9', 'Рене Альварес', 'Ассистентка Дэниела. Сидит за ресепшеном. Не спала всю ночь, но держится вежливо. Женщина 28–32 года, волосы собраны в пучок, строгая блузка, очки. Уставшее лицо, круги под глазами, но собранная.', NULL, NULL, 0, '2026-10-08 19:59:02.811397+00', '2026-10-08 23:44:46.228793+00', 49.020832, 57.345085, 1.059222, 0, NULL, 'AUTO', NULL);
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('dcd359b1-66f0-4a4c-a283-7aad43970907', '07501da7-4117-4722-9a5a-d824b70db044', NULL, 'Натали Уитмор', 'Жена Маркуса, работает в магазине Fern & Petal. Женщина 32–34 года, длинные светлые волосы, бледное лицо, без макияжа. Простая тёмная кофта, руки сжаты в замок. Растерянный, но не виноватый взгляд.', NULL, NULL, 0, '2026-10-08 19:55:39.558128+00', '2026-10-09 02:24:17.494465+00', 50, 50, 1, 0, NULL, 'EVIDENCE_FOUND', '0c80cf59-34b0-41d0-a95c-47ab2a5c6895');
INSERT INTO public.characters (id, case_id, location_id, name, description, biography, portrait_media_id, sort_order, created_at, updated_at, pos_x, pos_y, scene_scale, scene_rotation, dialogue_media_id, unlock_mode, unlock_target_id) VALUES ('80fde79f-d22c-43f3-a404-011c0c63ad6b', '07501da7-4117-4722-9a5a-d824b70db044', '235ae9f1-73a3-4119-b368-ca2cb4bef58a', 'Том Рейес', 'Мужчина 40–45 лет, полулежит на больничной койке, обе руки в бинтах, уставшее лицо.', NULL, NULL, 0, '2026-10-08 19:57:55.775831+00', '2026-10-08 23:43:42.128353+00', 49.440105, 23.580433, 2.4107988, 0, NULL, 'AUTO', NULL);
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('3bb0b441-3343-4569-9a90-94ce52a08467', 'c0b375be-b167-4427-954f-ca6d861d209d', 'Где была Натали в понедельник утром?', 'На смене, с утра и до пяти. Магазин у нас маленький — если бы она куда-то ушла, я бы заметила.', NULL, 0, '2026-10-09 00:52:24.017232+00', '2026-10-09 00:52:24.017232+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('3c2caabf-ac60-4d1e-b543-4fb58dfcce3d', 'c0b375be-b167-4427-954f-ca6d861d209d', 'А во вторник?', 'Утром была. В начале первого ей позвонил муж. Я слышала, как она сказала: «Не надо, у меня дела». Потом ушла — кажется, около без пятнадцати час. Плакала.', NULL, 0, '2026-10-09 00:52:41.672352+00', '2026-10-09 00:52:41.672352+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('f0e8ecd9-3744-4d4a-9771-c89b7a79108c', 'c0b375be-b167-4427-954f-ca6d861d209d', 'Куда ушла?', 'Сказала — к подруге. Клэр, кажется.', NULL, 0, '2026-10-09 00:53:09.371565+00', '2026-10-09 00:53:09.371565+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('598802b8-88a7-493f-a9dd-f05faa3a5848', 'c0b375be-b167-4427-954f-ca6d861d209d', 'Что вы о ней думаете?', 'В последнее время часто психует и срывается на всех.', NULL, 0, '2026-10-09 00:54:59.981354+00', '2026-10-09 00:54:59.981354+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('22788848-e311-4f05-8137-2c93e03ee903', '236b49ce-db70-40ab-9720-3d5545c11277', 'Где вы были во вторник днём?', 'На фабрике. В тест-кухне. Выбирал вкус для… для одного важного дня. Телефон оставил в шкафчике, чтобы не отвлекаться.', NULL, 0, '2026-10-09 01:00:05.630079+00', '2026-10-09 01:00:05.630079+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('3b3e730e-90a3-4466-933f-8674bdef2be3', '236b49ce-db70-40ab-9720-3d5545c11277', 'Когда вы узнали о пожаре?', 'Вышел из кухни около половины второго. Потом достал телефон и прочитал сообщение. Через несколько минут позвонили.', NULL, 0, '2026-10-09 01:00:42.831105+00', '2026-10-09 01:00:42.831105+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('02fb4010-285c-4d45-b895-928042378746', '236b49ce-db70-40ab-9720-3d5545c11277', 'Что вы можете сказать о брате?', 'Маркус держится. Он тоже потерял дом. Наверное, ему сейчас тяжелее, чем мне.', NULL, 0, '2026-10-09 01:01:10.423986+00', '2026-10-09 01:01:10.423986+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('a0ea1274-3ffa-42c2-99d2-97ad89296f1e', '5e9cddc7-dfb7-47e3-8e5e-4652d046a19b', 'Где вы были во вторник днём?', 'Выезжал по личным делам. За цветами жене.', NULL, 0, '2026-10-09 01:02:12.523468+00', '2026-10-09 01:02:12.523468+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('ce44a6d2-c878-4387-bea9-ddd2224946a4', '5e9cddc7-dfb7-47e3-8e5e-4652d046a19b', 'Когда вы последний раз видели брата?', 'Утром. Кажется, до обеда. Точно не помню.', NULL, 0, '2026-10-09 01:02:46.934566+00', '2026-10-09 01:02:46.934566+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('501551ff-e3d4-4d35-b910-5decf35de693', '5e9cddc7-dfb7-47e3-8e5e-4652d046a19b', 'Что вы знаете документах которые нашли в комнате вашей жены?', 'О каких документах? Я не понимаю, о чём вы.', NULL, 0, '2026-10-09 01:03:58.111959+00', '2026-10-09 01:03:58.111959+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('872c6c9f-6cd0-4855-9bb4-2a61fa492ee4', '93fe7e5c-bd6a-44cc-9fea-10e2637834ee', 'Когда Том Рейес забрал Лили?', 'Во вторник, в час пять, как всегда. Он у нас первый из родителей.', NULL, 0, '2026-10-09 01:04:20.031116+00', '2026-10-09 01:04:20.031116+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('f2b6d2f1-75b0-4e95-8062-9bf9e326b976', '93fe7e5c-bd6a-44cc-9fea-10e2637834ee', 'Он говорил что-то про работу?', 'Просил не говорить мистеру Уитмору про его отлучки. Хотя… мистер Маркус однажды занес пирог сам заходил и говорил об этом.', NULL, 0, '2026-10-09 01:05:18.818112+00', '2026-10-09 01:06:10.289807+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('903b6cd0-9f42-4f87-bdf1-d6ea33a52a12', '93fe7e5c-bd6a-44cc-9fea-10e2637834ee', 'Что за пирог?', 'Кажется, яблочный. Мистер Маркус вообще часто заходил, спрашивал про Лили. Такой внимательный.', NULL, 0, '2026-10-09 01:06:31.59592+00', '2026-10-09 01:06:31.59592+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('afd210d1-bb46-46d4-8fe1-67c42c6ecb85', 'dcd359b1-66f0-4a4c-a283-7aad43970907', 'Где вы были, когда начался пожар?', 'У юриста. Мне нужно было разобраться с бумагами.', NULL, 0, '2026-10-09 01:07:05.64482+00', '2026-10-09 01:07:05.64482+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('1d962aca-3c6a-4579-8bf6-1732ee360a93', 'dcd359b1-66f0-4a4c-a283-7aad43970907', 'С какими бумагами?', 'С личными.', NULL, 0, '2026-10-09 01:07:15.427981+00', '2026-10-09 01:07:15.427981+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('f9a2c986-8a92-4a5d-89fd-130361d414c4', 'dcd359b1-66f0-4a4c-a283-7aad43970907', 'Почему вы ехали к Клэр?', 'Мы дружили пятнадцать лет. Я хотела её увидеть. Неужели это теперь выглядит странно?', NULL, 0, '2026-10-09 01:07:34.143413+00', '2026-10-09 01:07:34.143413+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('36a8552c-62ba-4b0d-8b1e-c6f9caf65dab', 'dcd359b1-66f0-4a4c-a283-7aad43970907', 'Что вы думаете о муже?', 'Ничего. Не спрашивайте меня о нём.', NULL, 0, '2026-10-09 01:07:48.175539+00', '2026-10-09 01:07:48.175539+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('87118f40-2945-4470-923d-1bbdab93f9ef', '2498dfcf-2ead-4d13-b9a7-264aa00dab0f', 'Что происходило на фабрике днём?', 'Спокойно. Мистер Дэниел был на дегустации. В 12:25 заходил мистер Маркус, спрашивал его. Я ответила, что мистер Уитмор вышел.', NULL, 0, '2026-10-09 01:09:00.639842+00', '2026-10-09 01:09:00.639842+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('d2e42418-9b44-4ed2-9000-0c689ffb78da', '2498dfcf-2ead-4d13-b9a7-264aa00dab0f', 'Куда ушёл Маркус?', 'Сказал — по делам. Уехал на внедорожнике. Вернулся уже после того, как всё случилось.', NULL, 0, '2026-10-09 01:10:14.573507+00', '2026-10-09 01:10:14.573507+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('5499ffd4-1b4e-4dd5-bc54-83c4086ee61d', '80fde79f-d22c-43f3-a404-011c0c63ad6b', 'Что вы видели?', 'Вернулся около сорока минут второго. Ворота закрыты, огонь внутри. Разбил стекло, вошёл. Ожёг руки. Вытащить никого уже не смог. Я… я не знаю.', NULL, 0, '2026-10-09 01:10:46.272149+00', '2026-10-09 01:10:46.272149+00');
INSERT INTO public.character_dialogs (id, character_id, question, answer, requires_evidence_id, sort_order, created_at, updated_at) VALUES ('ef839440-4db2-421a-b3f1-fbeea66b0ec7', '80fde79f-d22c-43f3-a404-011c0c63ad6b', 'Почему вас не было на посту?', 'Отъезжал по делам. Мистер Уитмор разрешал. Он знал, что я быстро.', NULL, 0, '2026-10-09 01:11:54.533971+00', '2026-10-09 01:11:54.533971+00');
INSERT INTO public.figures (id, code, label, fallback_emoji, media_id, sort_order, active, created_at, updated_at) VALUES ('751ca008-ab61-435c-8f0d-64990bbb2728', 'figure-001', 'МОРГАН — Теневой детектив', '🕵️', NULL, 0, true, '2026-10-08 22:06:20.884774+00', '2026-10-08 22:06:20.884774+00');
INSERT INTO public.figures (id, code, label, fallback_emoji, media_id, sort_order, active, created_at, updated_at) VALUES ('474088b8-d212-4038-ac20-42c29262dab4', 'figure-002', 'КАСПЕР — Частный следователь', '🕵️', NULL, 0, true, '2026-10-08 22:06:43.067162+00', '2026-10-08 22:06:43.067162+00');
INSERT INTO public.figures (id, code, label, fallback_emoji, media_id, sort_order, active, created_at, updated_at) VALUES ('c75c5950-68e2-441b-abe9-64ed66a0e51d', 'figure-003', 'ЭВЕЛИН — Криминалист', '🕵️', NULL, 0, true, '2026-10-08 22:07:03.058797+00', '2026-10-08 22:07:03.058797+00');
INSERT INTO public.figures (id, code, label, fallback_emoji, media_id, sort_order, active, created_at, updated_at) VALUES ('553bbc3a-7b63-45ab-a0a1-dfa18b8aa65f', 'figure-004', 'АРИЯ — Следопыт', '🕵️', NULL, 0, true, '2026-10-08 22:07:18.565505+00', '2026-10-08 22:07:18.565505+00');
INSERT INTO public.final_questions (id, case_id, question_text, options, correct_option_id, explanation_text, reveal_evidence_ids, created_at, updated_at) VALUES ('32970f5a-aeb1-45fc-8c40-8e2442dc1013', '07501da7-4117-4722-9a5a-d824b70db044', 'Кто убил Клэр и Арабеллу Уитмор и поджёг оба дома? Или это чистая случайность и череда сопадений.', '[{"id": "free-form", "text": "Свободный ответ"}]', 'free-form', E'ВТОРНИК, 6 ОКТЯБРЯ\n\nВ то утро у Беллы поднялась температура. Дэниел сказал об этом\nбрату ещё до обеда — если что, сорвётся домой, работа подождёт.\nОн остался на фабрике, ушёл в тест-кухню выбирать вкус для дня\nрождения дочери, а телефон оставил в шкафчике, чтобы не отвлекаться.\nКлэр успела написать ему, что Белла уснула, температура спала, и\nпросила не приезжать — всё хорошо. Он это сообщение не прочитал.\nОно так и осталось висеть в шкафчике.\n\nМаркус зашёл в пустой кабинет брата около половины первого.\nАссистентка Рене сказала ему, что мистер Уитмор вышел — она имела\nв виду дегустацию. Маркус понял иначе: решил, что брат уехал домой,\nк дочери. Это было ему на руку. Он тут же позвонил жене и предложил\nзаехать пообедать. Натали ответила коротко: не надо, у меня дела.\nТогда он поехал к себе.\n\nВ своём доме он пробыл всего ничего. Вывез всё ценное — то, что\nне должно было сгореть, — и оставил на кухне самодельный таймер.\nК половине первого он уже мчал обратно, на фабрику. Дорожная камера\nна трассе Кедровый хребет зафиксировала его белый внедорожник, но\nводителя разглядеть не удалось.\n\nПока он ехал, охранник усадьбы Том Рейес отпросился с поста —\nпо вторникам он всегда сам забирал дочь из садика, и Дэниел это\nразрешал. Уехал он около без пяти час. Ворота остались заперты,\nкамера на столбе работала, но в саду была вторая камера — та,\nкоторую Маркус сам «сломал» ещё в субботу, оформив заявку\nв IT-отдел. Через прорезанную сетку в глубине сада он и вошёл\nна территорию усадьбы.\n\nВ это же время Натали припарковалась у офиса юриста. У неё был\nталон на приём с тринадцати ноль-двух до тринадцати сорока одного.\nОна хотела разобраться с бумагами — с теми самыми выписками,\nгде стояла её подпись, но не её рукой.\n\nВ пять минут второго Том забрал Лили из садика — как обычно,\nпервым из родителей.\n\nВ четверть второго на Кедровой, 14 начался пожар. Клэр погибла\nв гостиной, защищая дочь. Арабелле было шесть лет.\n\nМаркус вышел через сад и в тридцать две минуты уже был на фабрике.\nЧерез три минуты из тест-кухни вышел Дэниел — живой. Маркус\nувидел его в коридоре, поперхнулся, выронил стакан и только\nи успел выговорить: «Ты же…» — и замолчал. План дал трещину.\nК вечеру всё должно было решиться само, а брат оказался жив.\n\nДэниел достал из шкафчика телефон и прочитал последнее сообщение\nжены.\n\nТом к тому моменту уже вернулся — в тринадцать сорок, — увидел\nогонь, разбил стекло и полез внутрь. Вытащить никого не смог,\nобжёг обе руки.\n\nВ тринадцать сорок пять сработал таймер в доме на Кедровой, 9.\nВторой пожар, второй дом, вторая семья. Сосед позвонил в 13:48.\nА в тринадцать пятьдесят Натали приехала на Кедровую, 14 —\nс пионами, как обычно. Нашла Тома во дворе, вызвала скорую.\n\nМОТИВ\n\nМаркус годами выводил деньги из семейной фабрики через фиктивного\nпоставщика — компанию Cedar Citrus Supply. Всего около трёх\nмиллионов восьмисот тысяч. Договоры были оформлены на Натали,\nеё подпись подделана — ровной, слишком аккуратной рукой. Аудит\nдолжен был случиться в четверг, и Маркус знал об этом с пятницы.\n\nВ соглашении партнёров был пункт 7.3: если Дэниел и его прямые\nнаследники погибают, доля полностью переходит оставшемуся партнёру.\nФабрика стала бы его целиком.\n\nК этому он готовился заранее. Канистру бензина купил по карте\nлояльности Натали — чтобы следы вели к ней. В понедельник утром,\nкогда она стояла за кассой в магазине. Камеру в саду «сломал» сам,\nоформив заявку в IT как рядовой сотрудник. Перчатки с логотипом\nфабрики взял из лаборатории — на прошлой неделе он один оформлял\nтам пару. Всё складывалось в одну картину: подозреваемая — Натали.\nОн даже успел подбросить следствию её имя, когда давал показания:\nмол, в последнее время вела себя странно, всё спрашивала\nпро деньги.\n\nНо Дэниел выжил. Вышел из тест-кухни через двадцать минут после\nпожара и прочитал последнее сообщение жены. С этой секунды план\nМаркуса начал рассыпаться.\n\nКЛЭР И АРАБЕЛЛА\n\nКлэр погибла в гостиной, защищая дочь. Арабелле было шесть лет —\nдо её дня рождения оставалось восемь дней. Она не дожила до\nчетырнадцатого октября. Гирлянду с бумажными буквами «Белле 6»\nготовили заранее, и в календаре на кухне эта дата была обведена\nрозовым кругом.\n\nНатали в то утро ехала к подруге, чтобы рассказать, что нашла.\nОна собиралась уйти от мужа — но не успела. Юрист дал ей талон\nна приём с тринадцати ноль-двух до тринадцати сорока одного.\n\nСуд признал вину Маркуса Уитмора. Натали была оправдана.\nДэниел продолжил работать на фабрике. Первая коробка мармелада\nкаждой осени выходит с надписью на крышке: «Для Беллы».', '["7fe3ca77-1e80-4e40-9736-425957e6b2ae", "c536befc-9a65-4421-ad57-8db80ccc5531", "4f6a307b-b838-45f3-80d7-2cc835f92c4c", "fc43064f-3006-4706-ab6a-35ba1b6203b4", "b9edbc07-3125-48bb-87aa-a874188d0b18", "d4f3d325-3c1d-4446-8fe7-a3cad16b110f", "c3be39f2-7d6c-4970-8fb0-76df7a35f023", "eebd8ecf-8d01-4249-96b6-3651da9ac97f", "15545e32-32bc-43f6-9d63-76e194db2402", "cd5008c0-9142-4f1a-9bec-0eb6f0f40e8f", "9211c759-09b5-410d-98f1-cc343b01af18", "105be720-5f56-4ef3-a997-52105500e680", "9e500bac-d5df-4169-86ae-78a3ba83795c", "fe8f2e9f-6f72-4729-9895-d39b3d0a1eb4", "866ee725-93ea-4dfa-9578-0dd4a45bf871", "a4e8aaa0-ff8a-48c8-90ce-ee54146549b9", "503056bd-3747-42f9-9d6f-875e2fa646f5", "e6f6222b-b773-497b-85fd-02da546dbe94", "faef3dfc-8c15-48ec-9236-22a6cbaf59f3", "815fb73c-d58b-482e-96d9-2a9fb2b2f849", "b3042ea2-b04c-427f-8f34-29ca905e8a40", "930fdf2f-1b1a-4b58-99e8-ecefc7842cfc", "7c3ce91f-caf6-4896-93ac-7fe27c574cb1", "76e987d3-f1e2-4dae-a176-47d61373bba9", "e1b40375-52a1-44e2-b7c3-f28a8f6bb4ae", "2321e64a-7243-4b97-ab7c-982eb98edfb6", "121cafb6-c911-4d24-a48e-0c399b58ccf9"]', '2026-10-03 22:36:55.428534+00', '2026-10-09 22:02:34.800811+00');
