INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('bf3eaf1f-f22c-42b4-85e8-a422d13e9b2e', '07501da7-4117-4722-9a5a-d824b70db044', '4d1b01a0-7d8e-4475-ac3c-988cce1b7d05', 'SHOW_MESSAGE', NULL, 'В эфире шипение и обрывки фраз. Голоса не разобрать.', false, 10, '2026-10-06 20:38:53.189997+00', '2026-10-06 20:39:19.8726+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('86ed2acd-bea8-4543-a493-a1cd6098f0bd', '07501da7-4117-4722-9a5a-d824b70db044', '5d7d0bea-7f10-4f32-8579-1f71fc59e050', 'SHOW_MESSAGE', NULL, 'Кофе ещё не остыл. Здесь кто-то был пару минут назад.', true, 10, '2026-10-06 20:41:59.444542+00', '2026-10-06 20:41:59.444542+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('65a59f28-171f-4d33-a12c-e00fb106f667', '07501da7-4117-4722-9a5a-d824b70db044', '33feab91-f052-461b-abe6-4ac85fb2ccd2', 'UNLOCK_OBJECT', '869efa4c-817c-4278-9138-88f6e14b0249', NULL, true, 0, '2026-10-07 20:53:02.389809+00', '2026-10-07 20:53:02.389809+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('21dd7c2a-e0c7-4f36-aba9-e18106ed1b1f', '07501da7-4117-4722-9a5a-d824b70db044', 'c3483802-dcdd-4830-b08a-e46d0411dbd1', 'SHOW_MESSAGE', NULL, E'Аккуратный разрез в сетчатом заборе.\nТот, кто оставил перчатку,\nвошёл со стороны заднего двора, минуя ворота и камеру.\n\nЛоготип ведёт на фабрику Arabella''s Marmalade Co.\nОтправляйтесь туда, возможно, там что-то узнаете.', false, 0, '2026-10-07 23:31:05.882959+00', '2026-10-07 23:31:05.882959+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('e14f3a24-7215-48f4-acde-cf496cd76b02', '07501da7-4117-4722-9a5a-d824b70db044', '43115290-52d1-42ac-bd16-9c0956b3bfcb', 'UNLOCK_LOCATION', '235ae9f1-73a3-4119-b368-ca2cb4bef58a', NULL, true, 0, '2026-10-08 21:01:43.508363+00', '2026-10-08 21:01:43.508363+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('b1692840-8cc6-4af8-848a-b143c08b91d6', '07501da7-4117-4722-9a5a-d824b70db044', '99117b7f-4059-419f-988a-061e1fedd858', 'DISPATCH_CALL', NULL, 'Это Натали. Я приехала к Клэр сразу после работы — с пионами, как обычно. Возле дома был Том, он весь в ожогах. Я вызвала скорую. Его увезли в Mercy General. Съездите туда, может, он что-то помнит. Я сама ничего не видела.', true, 0, '2026-10-08 21:02:49.182301+00', '2026-10-08 21:02:49.182301+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('b9c26d29-24ef-49b8-b684-4de799d9b97a', '07501da7-4117-4722-9a5a-d824b70db044', '44bfa736-bca5-4d0c-82ec-d11fc37a86cc', 'DISPATCH_CALL', NULL, 'У охранника Тома есть дочь Лили. Она ходит в тот же садик, что и Белла Уитмор. Проверьте расписание садика.', true, 0, '2026-10-08 21:06:30.717609+00', '2026-10-08 21:06:30.717609+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('ebca14d8-a095-48bb-b2bd-6b48b3934cc4', '07501da7-4117-4722-9a5a-d824b70db044', 'ade5fdfd-02ab-4b95-9b55-7f18e9147655', 'DISPATCH_CALL', NULL, 'Камера 2 (задний двор) отключена в субботу 3 октября изнутри системы. Заявка оформлена штатно. Камера не работала три дня до пожара.', true, 0, '2026-10-08 21:07:29.81298+00', '2026-10-08 21:07:29.81298+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('7f286d07-cce6-4048-8270-6279676d3cab', '07501da7-4117-4722-9a5a-d824b70db044', '2779bdad-414d-4a3b-83b2-cba004859eea', 'UNLOCK_LOCATION', '1ec8fc06-7be9-4f0d-8fc0-8c02897f93e4', NULL, true, 0, '2026-10-08 21:08:08.009787+00', '2026-10-08 21:08:08.009787+00');
INSERT INTO public.game_events (id, case_id, condition_id, event_type, target_id, message, once, sort_order, created_at, updated_at) VALUES ('e2ccae95-3792-41f4-9531-3af3fbe5d554', '07501da7-4117-4722-9a5a-d824b70db044', 'f23933e4-3944-4eaf-bda4-b979fe36ea7f', 'DISPATCH_CALL', NULL, E'Телефон разблокирован. Экран подсвечивается, открыт\nсписок сообщений. Последний контакт — «Нэт».\n\nВторник, 6 октября\n\n12:20 → от Клэр → Дэну:\n«Белла уснула, температура спала.\nНе приезжай, всё хорошо ❤»\nСтатус: не прочитано.\n\n12:34 ← от Нэт:\n«Клэр, привет. Ты дома?»\n\n12:41 → Клэр → Нэт:\n«Да. Что-то случилось?»\n\n12:48 ← от Нэт:\n«Случилось. Я не могу это писать.\nМожно я заеду? Ненадолго.»\n\n12:49 → Клэр → Нэт:\n«Конечно. Белла спит, Дэн на работе.\nПриезжай, я сделаю чай.»\n\n12:50 ← от Нэт:\n«Еду. Есть новости. Только никому.\nПожалуйста.»\n\nБольше сообщений нет.\nПоследнее так и осталось непрочитанным — Клэр,\nвероятно, не успела открыть его.', true, 0, '2026-10-08 21:12:31.461678+00', '2026-10-08 21:12:31.461678+00');
